demo_out = [[int(x) for x in row.split()] for row in demo_output_str.strip().split('\n')]

# In demo, P = 4 (separator every 4 columns, every 4 rows)
P = 4

# Find special cells in input (non-5, non-2): values are 7 or 6
special_cells_demo = [(r, c, val) for r in range(len(demo_in)) 
                      for c in range(len(demo_in[0]))
                      if demo_in[r][c] not in [2, 5]]
print(f"Demo special cells: {special_cells_demo}")

# Now apply the rule: for each special cell at (r, c) with value v,
# fill all (r_i, c_i) where r_i = r (mod P), c_i = c (mod P)

def apply_transform(input_grid, P=4):
    rows = len(input_grid)
    cols = len(input_grid[0]) if rows > 0 else 0

    # Start with background
    output = [[0] * cols for _ in range(rows)]

    # Apply background filler first (this is what remains after special cells are placed)
    # Actually, we need to track what's already filled
    filled = [[False] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            v = input_grid[r][c]
            if v not in [2, 5]:  # Special cell
                for r_i in range(rows):
                    if r_i == r % P:
                        for c_i in range(cols):
                            if c_i == c % P:
                                # Check if this output position isn't already filled with another special
                                # Actually, I think we can overwrite or there's a priority
                                pass

    # Simpler approach: for each output position, find if it should be a special value
    # based on any special cell matching its (r mod P, c mod P)
    output = [[0] * cols for _ in range(rows)]
    background = 5  # Default background for demo

    for r_i in range(rows):
        for c_i in range(cols):
            # Find which (r, c) in input maps to this (r_i, c_i) via mod P
            for r in range(rows):
                if r % P == r_i % P:
                    for c in range(cols):
                        if c % P == c_i % P:
                            if input_grid[r][c] not in [2, 5]:
                                output[r_i][c_i] = input_grid[r][c]
                                break
                    else:
                        continue
                    break

    # Apply background to remaining cells
    for r_i in range(rows):
        for c_i in range(cols):
            if output[r_i][c_i] == 0:
                output[r_i][c_i] = background

    return output

demo_transformed = apply_transform(demo_in, P=4)
print("\nTransformed demo output:")
for i, row in enumerate(demo_transformed):
    print(f"Row {i}: {row}")
print(f"\nMatches original output: {demo_transformed == demo_out}")

